export function RoleWorkspaceDirectory({ onOpen }: { onOpen: (id: string) => void }) {
  const roleSpecs = roleWorkspaceSpecs.filter((spec) => spec.category === 'role');
  const personaSpecs = roleWorkspaceSpecs.filter((spec) => spec.category === 'persona');
  const renderGroup = (title: string, subtitle: string, specs: RoleWorkspaceSpec[]) => <section className="review-module-section"><div className="review-section-title"><div><h2>{title}</h2><p>{subtitle}</p></div><span className="review-section-count">{specs.length} experiences</span></div><div className="review-module-grid">{specs.map((spec, index) => { const Icon = spec.category === 'persona' ? BriefcaseBusiness : spec.id === 'role-worker' ? HardHat : spec.id === 'role-qa-qc' ? ShieldCheck : Users; return <article className="review-module-card" key={spec.id}><div className="review-module-card-top"><span className="review-module-icon"><Icon size={17} /></span><span className="review-card-status prototype">{spec.category === 'role' ? 'ROLE WORKSPACE' : 'BUSINESS PERSONA'}</span></div><h3>{String(index + 1).padStart(2, '0')} · {spec.home.ro}</h3><p>{spec.description.ro}</p><div className="review-module-card-footer"><span className="review-card-status">{spec.home.en}</span><button className="review-open-link" type="button" onClick={() => onOpen(spec.id)}>Open <ArrowRight size={13} /></button></div></article>; })}</div></section>;
  return <div className="role-directory">{renderGroup('ROLE WORKSPACES', 'Experiențe principale dedicate fiecărui rol · Design only', roleSpecs)}{renderGroup('BUSINESS PERSONAS', 'Concepte de spațiu de lucru pentru funcții organizaționale · fără roluri backend noi', personaSpecs)}</div>;
}

